// Mock daily site inspection reports (fictional) - stands in for a safety platform API
const inspections = [
  { inspection_id: 'INS-7001', site: 'Riverside Tower (demo)', inspector: 'Inspector A (demo)', area: 'Level 14 scaffolding', findings: 'Scaffold planking has a 3 ft gap and no guardrail on the open edge. Two workers observed without fall protection at 140 ft.', injuries_reported: 0 },
  { inspection_id: 'INS-7002', site: 'Harbor Warehouse (demo)', inspector: 'Inspector B (demo)', area: 'Trench excavation, east side', findings: 'Trench is 7 ft deep with no shoring or trench box. Worker was inside during inspection. Soil is sandy and wet.', injuries_reported: 0 },
  { inspection_id: 'INS-7003', site: 'Elm Street Apartments (demo)', inspector: 'Inspector C (demo)', area: 'Material storage yard', findings: 'Several pallets of drywall stacked unevenly and cluttering a walkway. No injuries; housekeeping issue only.', injuries_reported: 0 },
  { inspection_id: 'INS-7004', site: 'Riverside Tower (demo)', inspector: 'Inspector A (demo)', area: 'Ground floor electrical room', findings: 'Worker received an electrical shock from an ungrounded power tool and was taken to hospital for observation, admitted overnight.', injuries_reported: 1 },
  { inspection_id: 'INS-7005', site: 'Harbor Warehouse (demo)', inspector: 'Inspector B (demo)', area: 'Site office and entrance', findings: 'Two hard hats missing from the sign-in station and one fire extinguisher inspection tag expired last month.', injuries_reported: 0 }
];
return [{ json: { fetched_at: new Date().toISOString(), inspections } }];

